#!/usr/bin/env python3
"""
BMI DOCX - KIRISH + I BOB (final_2.py)
Opens BMI_final.docx and adds KIRISH (~10 pages) and I BOB (~30 pages)
"""
from docx import Document
from docx.shared import Pt, Cm
from docx.enum.text import WD_ALIGN_PARAGRAPH
import os

PATH = '/Users/baxrom/ish_full/dimlom_ishi/smart_street_light/docs/BMI/'
IMG = PATH + 'images/'
doc = Document(PATH + 'BMI_final.docx')

def bob(text):
    p = doc.add_heading(text, level=1)
    for r in p.runs:
        r.font.name = 'Times New Roman'; r.font.size = Pt(14); r.font.color.rgb = None

def h2(text):
    p = doc.add_heading(text, level=2)
    for r in p.runs:
        r.font.name = 'Times New Roman'; r.font.size = Pt(14); r.font.color.rgb = None

def t(x):
    p = doc.add_paragraph(x)
    p.paragraph_format.first_line_indent = Cm(1.25)
    p.paragraph_format.space_before = Pt(0); p.paragraph_format.space_after = Pt(0)
    for r in p.runs:
        r.font.name = 'Times New Roman'; r.font.size = Pt(14)

def img(name, caption):
    if not os.path.exists(IMG + name):
        return
    p = doc.add_paragraph()
    p.alignment = WD_ALIGN_PARAGRAPH.CENTER
    p.paragraph_format.first_line_indent = Cm(0)
    p.paragraph_format.space_before = Pt(0); p.paragraph_format.space_after = Pt(0)
    run = p.add_run()
    run.add_picture(IMG + name, width=Cm(14))
    pc = doc.add_paragraph()
    pc.alignment = WD_ALIGN_PARAGRAPH.RIGHT
    pc.paragraph_format.first_line_indent = Cm(0)
    pc.paragraph_format.space_before = Pt(0); pc.paragraph_format.space_after = Pt(0)
    rc = pc.add_run(caption); rc.italic = True; rc.font.size = Pt(12); rc.font.name = 'Times New Roman'

def tbl(headers, rows, caption):
    pc = doc.add_paragraph()
    pc.alignment = WD_ALIGN_PARAGRAPH.RIGHT
    pc.paragraph_format.first_line_indent = Cm(0)
    pc.paragraph_format.space_before = Pt(0); pc.paragraph_format.space_after = Pt(0)
    rc = pc.add_run(caption); rc.italic = True; rc.font.size = Pt(12); rc.font.name = 'Times New Roman'
    tb = doc.add_table(rows=1+len(rows), cols=len(headers))
    tb.style = 'Table Grid'
    for i, h in enumerate(headers):
        cell = tb.rows[0].cells[i]; cell.text = ''
        p = cell.paragraphs[0]
        p.paragraph_format.space_before = Pt(0); p.paragraph_format.space_after = Pt(0)
        r = p.add_run(h); r.bold = True; r.font.size = Pt(12); r.font.name = 'Times New Roman'
    for ri, row in enumerate(rows):
        for ci, v in enumerate(row):
            cell = tb.rows[ri+1].cells[ci]; cell.text = ''
            p = cell.paragraphs[0]
            p.paragraph_format.space_before = Pt(0); p.paragraph_format.space_after = Pt(0)
            r = p.add_run(str(v)); r.font.size = Pt(12); r.font.name = 'Times New Roman'

# ==================== KIRISH ====================
bob("KIRISH")

t("Zamonaviy shahar infratuzilmasida ko'cha yoritish tizimi muhim o'rin tutadi va u fuqarolarning xavfsizligini ta'minlash, transport harakatini tartibga solish hamda shahar muhitini yaxshilash kabi bir qator muhim vazifalarni bajaradi. Dunyo bo'yicha shaharlarda iste'mol qilinadigan elektr energiyasining o'rtacha yigirma besh foizdan qirq foizgacha bo'lgan qismi ko'cha yoritish tizimlariga sarflanadi, bu esa juda katta ko'rsatkich hisoblanadi. An'anaviy yoritish tizimlari tun bo'yi uzluksiz ishlaydi va bu jarayonda katta miqdorda energiya behuda sarflanadi, chunki ko'pchilik hollarda ko'chalarda piyodalar yoki transport vositalari bo'lmaydi. Ayniqsa, kam qatnov soatlarida yoki piyodalar umuman bo'lmagan vaqtlarda yoritgichlarning to'liq quvvatda ishlashi iqtisodiy jihatdan samarasiz hisoblanadi va bu muammo butun dunyo bo'ylab shaharlarda kuzatilmoqda. Shu sababli, energiya tejamkor aqlli yoritish tizimlarini ishlab chiqish bugungi kunning eng dolzarb muammolaridan biri bo'lib qolmoqda va bu sohadagi tadqiqotlar jadal sur'atlarda olib borilmoqda.")

t("Mavzuning dolzarbligi bir necha muhim omillar bilan belgilanadi va bu omillar global hamda mahalliy miqyosda ahamiyatga ega. Birinchidan, global miqyosda energiya resurslari cheklanganligi va ularning narxi yildan-yilga oshib borayotganligi sharoitida har bir soha bo'yicha tejamkorlik choralarini ko'rish zarur bo'lib, ko'cha yoritish bu borada eng katta potentsialga ega sohalardan biridir. Ikkinchidan, O'zbekiston Respublikasi hukumati tomonidan qabul qilingan yashil energetika va aqlli shahar konsepsiyalari doirasida innovatsion yechimlar talab etilmoqda va bu borada davlat dasturlari ishlab chiqilmoqda. Uchinchidan, Internet of Things texnologiyalarining jadal rivojlanishi arzon va samarali sensorli tizimlarni yaratish imkonini bermoqda, bu esa ilgari faqat katta korporatsiyalar uchun mavjud bo'lgan texnologiyalarni kichik loyihalarda ham qo'llash imkonini yaratmoqda. To'rtinchidan, atrof-muhit muhofazasi nuqtai nazaridan karbon izini kamaytirish global maqsadlarga mos keladi va Parij kelishuviga muvofiq barcha mamlakatlar o'z ulushini qo'shishi lozim.")

t("Ushbu bitiruv malakaviy ishining ilmiy yangiliklariga quyidagilar kiradi va ular mavjud yechimlardan tubdan farq qiladi. Ultratovush sensori va yorug'lik sensori ma'lumotlarini birgalikda qayta ishlash orqali ikki bosqichli harakat aniqlash algoritmi ishlab chiqilgan bo'lib, bu algoritm mavjud yechimlardan farqli ravishda ikkita mustaqil sensor ma'lumotlarini birlashtiradi. Ushbu algoritm debounce mexanizmi va gisterezis chegaralari yordamida soxta ishga tushishlarni minimallashtirib, energiya tejash samaradorligini oshiradi va tizimning ishonchliligini ta'minlaydi. Bundan tashqari, ESP32 mikrokontrolleri va Firebase bulutli platformasi integratsiyasi orqali real vaqt rejimida masofadan monitoring va boshqarish imkoniyati yaratilgan bo'lib, bu yondashuv arzon va samarali yechim sifatida taklif etilmoqda. Tizim adaptiv ravishda atrof-muhit sharoitlariga moslashadi va foydalanuvchi tomonidan belgilangan parametrlar asosida optimal ishlash rejimini tanlaydi, bu esa uni universal qo'llanilishi mumkin bo'lgan yechimga aylantiradi.")

t("Tadqiqotning maqsadi ultratovush sensori orqali harakatni aniqlash va energiya tejamkorligini ta'minlovchi aqlli ko'cha yoritish tizimini ishlab chiqishdan iborat bo'lib, bu tizim zamonaviy IoT texnologiyalari asosida quriladi. Tizim ko'cha yoritgichlarini faqat zarur bo'lgan hollarda yoqish orqali energiya sarfini kamaytirishga qaratilgan va bu maqsadga erishish uchun bir nechta sensorlar birgalikda ishlatiladi. Bunda sensorlar yordamida atrof-muhit sharoitlari doimiy ravishda kuzatiladi va yoritish darajasi avtomatik tarzda boshqariladi, bu esa inson aralashuvini minimal darajaga tushiradi. Masofadan boshqarish va monitoring imkoniyati tizimning moslashuvchanligini oshiradi hamda texnik xizmat ko'rsatish jarayonini soddalashtiradi, chunki barcha sozlamalar web interfeys orqali amalga oshiriladi. Tizim Progressive Web Application sifatida ishlab chiqilgan interfeys orqali istalgan qurilmadan boshqarilishi mumkin.")

t("Belgilangan maqsadga erishish uchun quyidagi vazifalar hal etilishi lozim va har bir vazifa tizimning muayyan jihatini qamrab oladi. Ko'cha yoritish sohasidagi mavjud yechimlar va texnologiyalarni tahlil qilish, ularning afzalliklari va kamchiliklarini aniqlash zarur bo'lib, bu tahlil yangi tizim uchun asos bo'ladi. Ultratovush sensori va yorug'lik sensori asosida harakatni aniqlash algoritmini ishlab chiqish va optimallash kerak, bunda debounce va gisterezis mexanizmlari qo'llaniladi. ESP32 mikrokontrolleri uchun dasturiy ta'minotni yaratish va sensorlar bilan integratsiyalash lozim, bu jarayonda PlatformIO muhiti va Arduino freymvorki ishlatiladi. Firebase bulutli platformasi orqali ma'lumotlarni saqlash va real vaqt rejimida sinxronlash tizimini qurish talab etiladi, bunda Realtime Database va Authentication xizmatlari qo'llaniladi. Foydalanuvchi interfeysi sifatida React asosida Progressive Web Application ishlab chiqish va tizimning energiya tejash samaradorligini eksperimental ravishda baholash zarur.")

t("Tadqiqot obyekti sifatida ko'cha yoritish tizimlarida energiya tejamkorligini ta'minlash jarayoni tanlab olingan bo'lib, bu jarayon zamonaviy shahar infratuzilmasining muhim tarkibiy qismi hisoblanadi. Tadqiqot predmeti esa ultratovush sensori va IoT texnologiyalari asosida aqlli yoritish tizimini loyihalash va amalga oshirish usullari hisoblanadi, bunda apparat va dasturiy ta'minot birgalikda ko'rib chiqiladi. Tadqiqot doirasida ESP32 mikrokontrolleri, RCWL-9610A ultratovush sensori, TEMT6000 yorug'lik sensori va WS2812B LED strip asosida prototip qurilma yaratilgan va u real sharoitlarda sinovdan o'tkazilgan. Prototip turar-joy massivi sharoitida bir hafta davomida uzluksiz ishlagan va olingan natijalar statistik jihatdan tahlil qilingan, bu esa tizimning ishonchliligini tasdiqlagan.")

t("Tadqiqotda quyidagi ilmiy usullar qo'llanilgan va har bir usul o'z o'rnida tizimning turli jihatlarini chuqur o'rganish imkonini bergan. Nazariy tahlil usuli mavjud adabiyotlar, ilmiy maqolalar va patent hujjatlarini o'rganish uchun ishlatilgan bo'lib, bu orqali sohadagi so'nggi yutuqlar va tendentsiyalar aniqlangan. Eksperimental usul prototipni yaratish va sinovdan o'tkazishda qo'llanilgan, bunda turli sharoitlarda tizimning ishlashi tekshirilgan va natijalar qayd etilgan. Modellashtirish usuli tizim arxitekturasini loyihalashda foydalanilgan va UML diagrammalari orqali tizim tuzilishi vizuallashtirilgan. Qiyosiy tahlil usuli mavjud tijorat yechimlari bilan solishtirishda ishlatilgan va bizning tizimimizning afzalliklari aniqlangan. Statistik tahlil usuli energiya tejash ko'rsatkichlarini baholashda qo'llanilgan va olingan natijalarning ishonchliligi tekshirilgan.")

t("Ishning amaliy ahamiyati shundaki, ishlab chiqilgan tizim real sharoitlarda qo'llanilishi mumkin bo'lgan tayyor yechim hisoblanadi va u minimal xarajat bilan joriy etilishi mumkin. Tizim oltmish foizdan sakson foizgacha energiya tejash imkonini beradi, bu esa yiliga katta miqdorda mablag' tejashga olib keladi va investitsiya olti oydan bir yil ichida qaytadi. Masofadan boshqarish imkoniyati texnik xizmat ko'rsatish xarajatlarini kamaytiradi, chunki barcha sozlamalar va monitoring web interfeys orqali amalga oshiriladi. PWA interfeysi orqali tizimni istalgan qurilmadan, jumladan smartfon, planshet yoki kompyuterdan boshqarish mumkin. Loyiha natijalari O'zbekiston shaharlarida aqlli yoritish tizimlarini joriy etishda amaliy qo'llanma sifatida foydalanilishi mumkin va mahalliy sharoitlarga moslashtirilgan. Bundan tashqari, ishlab chiqilgan dasturiy ta'minot ochiq kodli bo'lib, boshqa tadqiqotchilar tomonidan kengaytirilishi va takomillashtirilishi mumkin, bu esa ilmiy hamjamiyatga hissa qo'shadi.")

t("Bitiruv malakaviy ishi kirish, uchta bob, xulosa va ilovalardan tashkil topgan bo'lib, har bir qism tizimning muayyan jihatini qamrab oladi. Kirish qismida mavzuning dolzarbligi, ilmiy yangiligi, maqsad va vazifalari, tadqiqot obyekti va predmeti, qo'llanilgan usullar hamda amaliy ahamiyati bayon etilgan. Birinchi bobda ko'cha yoritish tizimlarining nazariy asoslari, mavjud yechimlar tahlili, sensorli texnologiyalar va IoT protokollari haqida batafsil ma'lumot berilgan. Ikkinchi bobda tizimning dasturiy va apparat ta'minoti, arxitekturasi, ma'lumotlar bazasi tuzilishi va amalga oshirish jarayoni batafsil yoritilgan. Uchinchi bobda eksperimental natijalar, energiya tejash ko'rsatkichlari, tizim samaradorligi va qiyosiy tahlil keltirilgan. Xulosa qismida olingan natijalar umumlashtirilgan, xulosalar chiqarilgan va kelgusi istiqbollar belgilangan.")

